from qbank_authoring import ref
CT=ref('ERS/EULAR: Connective Tissue Disease-Associated ILD Guideline','https://publications.ersnet.org/content/erj/67/1/2402533')
SS=ref('ATS: Treatment of Systemic Sclerosis-Associated ILD, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC10806429/')
BS=ref('British Society for Rheumatology: Systemic Sclerosis Guideline, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11534099/')
FL=ref('Fleischner Society: Standardized Clinical Terms and Definitions for ILD','https://doi.org/10.1164/rccm.202505-1142SO')
LC=ref('International Adult Langerhans Cell Histiocytosis Consensus, 2022','https://pmc.ncbi.nlm.nih.gov/articles/PMC11022927/')
LA=ref('ATS/JRS: LAM Diagnosis and Management Guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC5803656/')
